"using Microsoft.EntityFrameworkCore;
using KtsVinhLong.Models;

namespace KtsVinhLong.Data
{
    public class KtsDbContext : DbContext
    {
        public KtsDbContext(DbContextOptions<KtsDbContext> options) : base(options)
        {
        }

        public DbSet<KhungKts> KhungKts { get; set; } = null!;
        public DbSet<DonVi> DonVis { get; set; } = null!;
        public DbSet<HeThongSo> HeThongSos { get; set; } = null!;
        public DbSet<NhiemVu> NhiemVus { get; set; } = null!;
        public DbSet<User> Users { get; set; } = null!;

        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            base.OnModelCreating(modelBuilder);

            // Cấu hình các ràng buộc đặc biệt nếu cần thiết
            modelBuilder.Entity<DonVi>()
                .HasMany(d => d.Children)
                .WithOne(d => d.Parent)
                .HasForeignKey(d => d.ParentId)
                .OnDelete(DeleteBehavior.Restrict);

            modelBuilder.Entity<User>()
                .HasIndex(u => u.Email)
                .IsUnique();
        }
    }
}
"

