"using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using KtsVinhLong.Data;
using KtsVinhLong.Models;
using System.Linq;
using System.Threading.Tasks;

namespace KtsVinhLong.Controllers
{
    public class PortalController : Controller
    {
        private readonly KtsDbContext _context;

        public PortalController(KtsDbContext context)
        {
            _context = context;
        }

        public IActionResult Index()
        {
            return View();
        }

        public async Task<IActionResult> HienTrang(int lop = 1)
        {
            var systems = await _context.HeThongSos
                .Include(h => h.DonVi)
                .Where(h => h.Lop == lop)
                .ToListAsync();

            ViewBag.ActiveLop = lop;
            return View(systems);
        }
    }
}
"

