"using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using KtsVinhLong.Data;
using KtsVinhLong.Models;
using System.Linq;
using System.Threading.Tasks;

namespace KtsVinhLong.Controllers
{
    // [Authorize] - Đã bỏ theo yêu cầu của bạn
    public class AdminController : Controller
    {
        private readonly KtsDbContext _context;

        public AdminController(KtsDbContext context)
        {
            _context = context;
        }

        public async Task<IActionResult> Index()
        {
            var tongHeThong = await _context.HeThongSos.CountAsync();
            var tongNhiemVu = await _context.NhiemVus.CountAsync();
            var nhiemVuHoanThanh = await _context.NhiemVus.CountAsync(n => n.TrangThai == "hoan-thanh");
            var nhiemVuTreHan = await _context.NhiemVus.CountAsync(n => n.TrangThai == "tre-han");

            ViewBag.TongHeThong = tongHeThong;
            ViewBag.TongNhiemVu = tongNhiemVu;
            ViewBag.NhiemVuHoanThanh = nhiemVuHoanThanh;
            ViewBag.NhiemVuTreHan = nhiemVuTreHan;

            ViewBag.PhanTramHoanThanh = tongNhiemVu > 0 ? (nhiemVuHoanThanh * 100 / tongNhiemVu) : 0;

            return View();
        }

        public async Task<IActionResult> HeThong()
        {
            var systems = await _context.HeThongSos.Include(h => h.DonVi).ToListAsync();
            return View(systems);
        }

        public async Task<IActionResult> NhiemVu()
        {
            var tasks = await _context.NhiemVus.Include(n => n.DonViChuTri).ToListAsync();
            return View(tasks);
        }
    }
}
